<template>
 <section ref="host" class="integration-figure" :data-integration-chart="chartId">
  <header><h3>{{ chartId }} · {{ title }}</h3><span v-if="figure">{{ figure.status }} · n={{ number(figure.n_valid) }}</span></header>
  <ModuleState v-if="!figure||figure.status==='queued'" state="loading" title="Preparing versioned scientific result" />
  <ModuleState v-else-if="['unavailable','invalid_source','failed'].includes(figure.status)" :state="figure.status==='failed'?'error':'missing'" title="Result unavailable for this population" :retry="figure.status==='failed'?()=>context.retryChart(chartId):undefined" :message="figure.reason||'Required evidence is absent. Original Core distributions remain available.'" />
  <template v-else>
   <p v-if="figure.status==='partial'" class="integration-note">Partial evidence: {{ figure.reason||figure.data?.supplement?.missing_full_columns?.join(', ')||'Optional Genome Full components are unavailable; see source audit.' }}</p>
   <div v-if="['OV02','OV03'].includes(chartId)" class="integration-toolbar"><label>Find seqid <input v-model="trackSearch" placeholder="All registered seqids" /></label><label>Start (bp) <input v-model="rangeLo" type="number" min="0" /></label><label>End (bp) <input v-model="rangeHi" type="number" min="0" /></label><button class="btn subtle" :disabled="trackPage===1" @click="trackPage--">Previous tracks</button><span>{{ trackTotal }} seqids · page {{ trackPage }}</span><button class="btn subtle" :disabled="trackPage*6>=trackTotal" @click="trackPage++">Next tracks</button></div>
   <p v-if="coordinateError" role="alert">{{ coordinateError }}</p>
   <div v-if="['CGT','CGP','CTP','CX13'].includes(chartId)" class="integration-toolbar"><label>Locate field / ID <input v-model="matrixSearch" placeholder="Original name or G/T/P field ID" /></label><span>Moves the viewport; all cells remain in the matrix and export.</span></div>
   <div class="integration-toolbar"><button class="btn subtle" @click="save('svg')">SVG</button><button class="btn subtle" @click="save('png')">PNG 4×</button><a :href="download('chart_data')">Figure data JSON</a><a :href="download('gene_valid_counts')">All field support counts CSV</a><a :href="download(csvKind)">{{ ['OV01','CX14','CX15','CX16','XS01'].includes(chartId)?'Complete cohort JSON':'Complete result CSV' }}</a><button class="btn subtle" @click="methods=!methods">{{ methods?'Hide method':'View method' }}</button></div>
   <p v-if="exportError" role="alert">{{ exportError }}</p>
   <div class="integration-scroll"><div :style="{minWidth:minimumWidth+'px'}"><EChart :option="option" :height="height" :show-exports="false" :auto-loading="false" @chart-click="clicked" /></div></div>
   <div v-if="secondary" class="integration-secondary"><p>{{ secondaryLabel }}</p><EChart :option="secondary" :height="280" :show-exports="false" :auto-loading="false" /></div>
   <details v-if="['OV02','OV03'].includes(chartId)"><summary>Exact native windows in the displayed tracks</summary><p>Track/range controls select original windows for display. Global thresholds and whole-window member counts stay fixed.</p><div class="integration-scroll"><table class="table compact-table"><thead><tr><th>Seqid</th><th>Start (bp)</th><th>End (bp)</th><th>Median</th><th>Records</th><th>Members</th></tr></thead><tbody><template v-for="track in display.data.tracks" :key="track.seqid"><tr v-for="window in track[chartId]" :key="window.selection_id"><td>{{ track.seqid }}</td><td>{{ number(window.start) }}</td><td>{{ number(window.end) }}</td><td>{{ number(window.median) }}</td><td>{{ window.n }}</td><td><button class="ghost-link" :disabled="!window.n" @click="$emit('selection',{chart_id:chartId,selection_id:window.selection_id,expected:window.n})">Inspect window</button></td></tr></template></tbody></table></div></details>
   <p class="integration-caption">{{ figure.population }} · n_source={{ number(figure.n_source) }}, n_valid={{ number(figure.n_valid) }}. {{ figure.caveats }}</p>
   <p class="integration-provenance">{{ speciesId }} · {{ chartId }} · {{ figure.method_version }} · artifact {{ figure.artifact_version }}<br>{{ figure.cohort_key?'cohort '+figure.cohort_key+' / '+figure.cohort_version:'source '+figure.source_hash }}</p>
   <details v-if="methods" open><summary>Calculation and provenance</summary><p>{{ figure.method }}</p><p>{{ figure.unit }}</p><pre>{{ JSON.stringify(figure.parameters,null,2) }}</pre><a :href="download('methods')">Complete source and methods JSON</a></details>
  </template>
 </section>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import EChart from '../EChart.vue'
import ModuleState from '../ModuleState.vue'
import {integrationOption,integrationHeight,integrationDistribution,integrationNumber as number} from '../../utils/integrationCharts'
import {integrationFieldLabels} from '../../utils/integrationFields.js'
import {exportIntegration} from '../../utils/integrationExport'
import {integrationExport} from '../../api/integrationVisuals'
const props=defineProps({chartId:String,figure:Object,speciesId:String,context:Object});const emit=defineEmits(['selection','entity']);const host=ref(),methods=ref(false),exportError=ref(''),trackSearch=ref(''),trackPage=ref(1),rangeLo=ref(''),rangeHi=ref(''),coordinateResult=ref(null),coordinateError=ref(''),matrixSearch=ref('');let observer,coordinateSeq=0,coordinateVersion=''
const titles={OV01:'Three-omics species fingerprint',OV02:'Native Genome composition tracks',OV03:'Promoter − exon GC contrast',OV04:'DNA → RNA nitrogen resource shift',OV05:'RNA → Protein nitrogen resource shift',CX01:'X0 · Source records and anchored genes',CX02:'X0 · Anchored gene coverage and disjoint sets',CX03:'X1 · DNA → RNA resource distribution',CX04:'X1 · RNA → Protein resource distribution',CX05:'X1 · Full-population resource density',CX06:'X1 · Direction quadrants',CX07:'X2 · Exon and RNA GC agreement',CX08:'X3 · RNA GC and protein nitrogen cost',CX09:'X3 · Conditional pI ridge distributions',CX10:'X3 · GRAVY empirical quantile bands',CX11:'X4 · Exact transcript-paired pI agreement',CX12:'X5 · Three-set outlier intersections',CX13:'X6 · Representative complete coupling matrix',CGT:'X6 · Genome × RNA complete matrix',CGP:'X6 · Genome × Protein complete matrix',CTP:'X6 · RNA × Protein complete matrix',CX14:'X7 · Named species fingerprint',CX15:'X7 · Species PCA and complete PC1 loadings',CX16:'X7 · Same-cohort Euclidean distances',CX17:'Resource strata conditional contingency',XS01:'X7 · All descriptor variability',XS02:'X8 · Complete eligible ranking',XS03:'X8 · All selected candidate evidence',XS04:'X6 · Complete finite correlation distribution'}
const title=computed(()=>titles[props.chartId]||props.chartId)
const filteredTracks=computed(()=>coordinateResult.value?.items||props.figure?.data?.tracks||[])
const trackTotal=computed(()=>coordinateResult.value?.total??props.figure?.data?.tracks_total??filteredTracks.value.length)
watch([trackSearch,rangeLo,rangeHi],()=>trackPage.value=1)
async function loadCoordinates(){if(!['OV02','OV03'].includes(props.chartId))return;if(coordinateVersion!==props.figure?.artifact_version){coordinateResult.value=null;coordinateVersion=props.figure?.artifact_version||'';coordinateSeq++}if(!props.figure?.artifact_version)return;const seq=++coordinateSeq,id=props.speciesId,version=props.figure.artifact_version
 try{const range=rangeLo.value!==''||rangeHi.value!==''?`${rangeLo.value||0},${rangeHi.value||Number.MAX_SAFE_INTEGER}`:undefined;const r=await props.context.get('coordinates/',{chart_id:props.chartId,page:trackPage.value,page_size:6,search:trackSearch.value,range});if(seq===coordinateSeq&&id===props.speciesId&&version===props.figure?.artifact_version){coordinateResult.value=r;coordinateError.value=''}}catch(e){if(seq===coordinateSeq)coordinateError.value=e?.response?.data?.error?.message||e.message}
}
watch([()=>props.figure?.artifact_version,trackSearch,trackPage,rangeLo,rangeHi],loadCoordinates,{immediate:true})
const display=computed(()=>!props.figure?null:{...props.figure,...(['OV02','OV03'].includes(props.chartId)?{data:{...props.figure.data,tracks:filteredTracks.value}}:{})})
const option=computed(()=>{const o=integrationOption(display.value);if(matrixSearch.value&&['CGT','CGP','CTP','CX13'].includes(props.chartId)){const needle=matrixSearch.value.toLowerCase(),find=keys=>keys.findIndex(k=>(k+' '+(integrationFieldLabels[k]||'')).toLowerCase().includes(needle)),row=find(display.value.data.rows),col=find(display.value.data.columns);o.dataZoom=[{type:'slider',xAxisIndex:0,bottom:58,start:col<0?0:Math.max(0,col-3)/display.value.data.columns.length*100,end:col<0?100:Math.min(display.value.data.columns.length,col+17)/display.value.data.columns.length*100},{type:'slider',yAxisIndex:0,right:5,start:row<0?0:Math.max(0,row-3)/display.value.data.rows.length*100,end:row<0?100:Math.min(display.value.data.rows.length,row+17)/display.value.data.rows.length*100}]}o.graphic=[...(o.graphic||[]),{type:'text',left:12,bottom:4,silent:true,style:{text:`${props.speciesId} · ${props.chartId} · n=${props.figure?.n_valid??'—'}\n${props.figure?.method_version||''} · artifact ${props.figure?.artifact_version||''} · ${(props.figure?.cohort_key?'cohort '+props.figure.cohort_key:('source '+(props.figure?.source_hash||''))).slice(0,32)}`,fontSize:10,lineHeight:13,fill:'#556775'}}];return o})
const height=computed(()=>integrationHeight(display.value)),minimumWidth=computed(()=>['CGT','CGP','CTP','CX13','CX15','XS03'].includes(props.chartId)?820:520)
const secondary=computed(()=>['OV03','CX07','CX10','CX11','XS02'].includes(props.chartId)&&props.figure?.data?.distribution?integrationDistribution(props.figure.data.distribution,secondaryLabel.value,true):null)
const secondaryLabel=computed(()=>({OV03:'All finite promoter − exon GC contrasts (pp), including unlocated records',CX07:'RNA − exon GC contrast (pp)',CX10:'All pairwise-valid GRAVY records',CX11:'Absolute sequence-derived pI difference',XS02:'All eligible candidate scores'})[props.chartId])
const csvKind=computed(()=>['OV01','CX14','CX15','CX16','XS01'].includes(props.chartId)?'cohort':props.chartId==='CX11'?'exact_pairs':['OV02','OV03'].includes(props.chartId)?'native_components':['CX01','CX07','CX08','CX09','CX10'].includes(props.chartId)?'table':props.chartId==='CX02'?'gene_matrix':['CGT','CGP','CTP','CX13','XS04'].includes(props.chartId)?'correlations':['XS02','XS03'].includes(props.chartId)?'candidates':'chain_rows')
function download(kind){const cid=props.chartId,table=cid==='CX01'?'x0_mapping':cid==='CX07'?'x2_gc':['CX08','CX09','CX10'].includes(cid)?'x3_members':undefined;return integrationExport(props.speciesId,{...props.context.params(),kind,chart_id:cid,omics:'genome',table_id:kind==='table'?table:undefined,selected:kind==='candidates'?cid==='XS03':undefined,layer_pair:kind==='correlations'?cid==='CX13'?'representative':['CGT','CGP','CTP'].includes(cid)?cid:undefined:undefined,cohort_version:props.figure?.cohort_version})}
async function save(format){exportError.value='';try{await exportIntegration(option.value,{format,title:`${props.chartId} · ${title.value}`,name:`${props.speciesId}_${props.chartId}_${props.figure.artifact_version}`,height:height.value})}catch(e){exportError.value=e.message}}
function clicked(e){const raw=e?.data?.raw;if(raw?.selection_id)emit('selection',{chart_id:props.chartId,selection_id:raw.selection_id,expected:raw.count??raw.n});else if(raw?.feature_a&&raw?.feature_b&&raw?.pair_n!==undefined)emit('selection',{chart_id:props.chartId,selection_id:`pair:${raw.feature_a}:${raw.feature_b}`,expected:raw.pair_n});else if(raw?.gene_id)emit('entity',{gene_id:raw.gene_id,entity_id:raw.gene_id,entity_type:'gene',report_entity_key:raw.gene_id})}
onMounted(()=>{observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){props.context.want([props.chartId]);observer.disconnect()}},{rootMargin:'400px'});observer.observe(host.value)});onBeforeUnmount(()=>observer?.disconnect())
</script>
